        f, a = word[k]
        g, b = word[k + 1]
        if f == g and a == b:
            memo[word] = {}
            return memo[word]
        if f < g or (f == g and a > b):
            swapped = word[:k] + (word[k + 1], word[k]) + word[k + 2:]
            result = {w: -c for w, c in car(swapped, memo).items()}
            if f == 0 and g == 1 and a == b:
                contracted = word[:k] + word[k + 2:]
                for w, c in car(contracted, memo).items():
                    result[w] = result.get(w, 0) + c
            result = {w: c for w, c in result.items() if c}
            memo[word] = result
            return result
    memo[word] = {word: 1}
    return memo[word]

