    modes = sorted(set(mode for flag, mode in word))
    ranks = {mode: k for k, mode in enumerate(modes)}
    shape = tuple((flag, ranks[mode]) for flag, mode in word)
    return {tuple((flag, modes[rank]) for flag, rank in w): c
            for w, c in car(shape, memo).items()}

