        for b in range(a, len(groups)):
            pb, qb = groups[b]
            key = (pa, pb)
            if key not in kernels:
                middle = tuple((0, m) for m in pa) + tuple((1, m) for m in pb)
                kernels[key] = [(tuple(m for c, m in w if c), tuple(m for c, m in w if not c), v) for w, v in normal(middle).items()]
            polynomial = {}
            for creators, annihilators, coefficient in kernels[key]:
                creators, cs = exterior(qa, creators, merges)
                if cs:
                    annihilators, ds = exterior(annihilators, qb, merges)
                    if ds:
                        value = signs[a] * coefficient * cs * ds
                        word = (creators, annihilators)
                        polynomial[word] = polynomial.get(word, 0) + value
                        if a != b:
                            word = (annihilators, creators)
                            value *= adjoint_sign(creators, annihilators)
                            polynomial[word] = polynomial.get(word, 0) + value
            terms = [(word, value) for word, value in polynomial.items() if value]
            if terms:
                lift = weights(columns[a], columns[b], a == b)
                for word, coefficient in terms:
                    row = result.setdefault(word, {})
                    for coordinate, value in lift:
                        row[coordinate] = row.get(coordinate, 0) + coefficient * value
    output = {}
    for (creators, annihilators), row in result.items():
        row = {coordinate: value for coordinate, value in row.items() if value}
        if row:
            word = tuple((1, m) for m in creators) + tuple((0, m) for m in annihilators)
            output[word] = row
    return output
